    nms <- names(x)
    if (is.null(nms)) {
      if (length(x) == 0) return("[]")
      parts <- vapply(x, json_one, character(1))
      return(paste0("[", paste(parts, collapse = ","), "]"))
    }
    if (length(x) == 0) return("{}")
    parts <- character(length(x))
    for (i in seq_along(x)) {
      parts[[i]] <- paste0(json_str(nms[[i]]), ":", json_one(x[[i]]))
    }
    return(paste0("{", paste(parts, collapse = ","), "}"))
  }
  json_atom(x)
}

